        rom[486] = {11'h209, 21'h0bf19a, 30'h1d865fd5};
        rom[487] = {11'h208, 21'h0bed88, 30'h1d7a7044};
        rom[488] = {11'h207, 21'h0be978, 30'h1d6e84c4};
        rom[489] = {11'h206, 21'h0be56a, 30'h1d629d53};
        rom[490] = {11'h205, 21'h0be15f, 30'h1d56b9ef};
        rom[491] = {11'h203, 21'h0bdd56, 30'h1d4ada94};
        rom[492] = {11'h202, 21'h0bd94f, 30'h1d3eff42};
        rom[493] = {11'h201, 21'h0bd54b, 30'h1d3327f5};
        rom[494] = {11'h200, 21'h0bd149, 30'h1d2754ab};
        rom[495] = {11'h1ff, 21'h0bcd49, 30'h1d1b8563};
        rom[496] = {11'h1fe, 21'h0bc94b, 30'h1d0fba18};
        rom[497] = {11'h1fc, 21'h0bc550, 30'h1d03f2cb};
        rom[498] = {11'h1fb, 21'h0bc157, 30'h1cf82f77};
        rom[499] = {11'h1fa, 21'h0bbd60, 30'h1cec701c};
        rom[500] = {11'h1f9, 21'h0bb96c, 30'h1ce0b4b6};
        rom[501] = {11'h1f8, 21'h0bb57a, 30'h1cd4fd43};
        rom[502] = {11'h1f7, 21'h0bb18a, 30'h1cc949c1};
        rom[503] = {11'h1f6, 21'h0bad9c, 30'h1cbd9a2e};
        rom[504] = {11'h1f5, 21'h0ba9b0, 30'h1cb1ee88};
        rom[505] = {11'h1f4, 21'h0ba5c7, 30'h1ca646cc};
        rom[506] = {11'h1f2, 21'h0ba1e0, 30'h1c9aa2f9};
        rom[507] = {11'h1f1, 21'h0b9dfb, 30'h1c8f030b};
        rom[508] = {11'h1f0, 21'h0b9a18, 30'h1c836702};
        rom[509] = {11'h1ef, 21'h0b9638, 30'h1c77ced9};
        rom[510] = {11'h1ee, 21'h0b925a, 30'h1c6c3a91};
        rom[511] = {11'h1ed, 21'h0b8e7d, 30'h1c60aa25};
    end
    assign rc = frac[RW+K-1 -: K] >= 212;
    reg [WROM-1:0] rom_q;
    reg [RW-1:0]   w_r;
    reg            v_r;
    always @(posedge clk) begin
        if (rst) v_r <= 1'b0;
        else     v_r <= in_valid;
        rom_q <= rom[frac[RW+K-1 -: K]];
        w_r   <= frac[RW-1:0];
    end
    wire [W0-1:0] c0 = {1'b1, rom_q[W0-2:0]};
    wire [W1-1:0] c1 = rom_q[30 +: W1];
    wire [W2-1:0] c2 = rom_q[51 +: W2];

    // c0 - c1*w, the wide product, held if the chain takes longer.
    wire v_p;
    wire [W1+T1-1:0] p1;
    _zkf_pmul #(
        .WA(W1), .WB(T1), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT)
    ) u_p1 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c1), .b(w_r[RW-1 -: T1]),
        .out_valid(v_p), .sb_out(), .p(p1)
    );
    wire [W0-1:0] c0_d;
    zkf_pipe #(.W(W0), .N(NK)) u_c0 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c0), .out_valid(), .out(c0_d)
    );
    wire [W1-1:0] p1_d;
    zkf_pipe #(.W(W1), .N(NK - 1 - STAGE_PRODUCT)) u_p1_d (
        .clk(clk), .rst(rst), .in_valid(v_p), .in(p1[W1+T1-1:T1]), .out_valid(out_valid), .out(p1_d)
    );

    wire [TS-1:0] ws = w_r[RW-1 -: TS];
    wire v_s;  // the valid of the square
    wire [W2-1:0] c2_s;
    zkf_pipe #(.W(W2), .N(STAGE_PRODUCT_SQUARE)) u_c2 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c2), .out_valid(), .out(c2_s)
    );
    // chain = c2 * w**2, registered as the bits the last sum takes.
    wire [TS+TS-1:0] sq;
    _zkf_pmul #(
        .WA(TS), .WB(TS), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(SQP), .STAGE_OUTPUT(SQO)
    ) u_sq (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(ws), .b(ws),
        .out_valid(v_s), .sb_out(), .p(sq)
    );
    wire [W2+Q0-1:0] p2;
    _zkf_pmul #(
        .WA(W2), .WB(Q0), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_CHAIN), .STAGE_OUTPUT(0)
    ) u_p2 (
        .clk(clk), .rst(rst), .in_valid(v_s), .sb_in(1'b0), .a(c2_s), .b(sq[2*TS-1 -: Q0]),
        .out_valid(), .sb_out(), .p(p2)
    );
    wire [W2-1:0] p2_d;
    zkf_pipe #(.W(W2), .N(NK - NL)) u_p2_d (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(p2[W2+Q0-1:Q0]), .out_valid(), .out(p2_d)
    );
    reg  [W2-1:0] chain;
    always @(posedge clk) chain <= p2_d;
    assign c = c0_d - p1_d + chain;
endmodule

